    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty_remaining, seq]
    seq_counter = 0

    def add_order(order_id, side, price, seq):
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
